import{_ as e,o as l,c as a,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const q=JSON.parse('{"title":"递延税复利 Deferred Tax Compounding","description":"巴菲特最被低估的秘密：未实现资本利得递延纳税，复利优势的隐形翅膀","frontmatter":{"title":"递延税复利 Deferred Tax Compounding","description":"巴菲特最被低估的秘密：未实现资本利得递延纳税，复利优势的隐形翅膀"},"headers":[],"relativePath":"02_concepts/deferred-tax.md","filePath":"02_concepts/deferred-tax.md"}'),r={name:"02_concepts/deferred-tax.md"};function i(n,t,h,u,s,d){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="递延税复利-deferred-tax-compounding" tabindex="-1">递延税复利 Deferred Tax Compounding <a class="header-anchor" href="#递延税复利-deferred-tax-compounding" aria-label="Permalink to &quot;递延税复利 Deferred Tax Compounding&quot;">​</a></h1><blockquote><p>1989年，巴菲特在致股东信中首次系统阐述了一个&quot;几乎从未被人讨论过&quot;的竞争优势——<strong>递延税的复利效应</strong>。这是巴菲特70年投资生涯中最被低估的主题之一。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1989年/翻译.html">1989年翻译</a></strong></td><td style="text-align:left;">首次系统阐述递延税复利哲学</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2000年/翻译.html">2000年翻译</a></strong></td><td style="text-align:left;">透视盈利框架下递延税的意义</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2019年/翻译.html">2019年翻译</a></strong></td><td style="text-align:left;">留存收益与递延税的长期关系</td></tr></tbody></table><hr><h2 id="一、被忽视的隐形优势" tabindex="-1">一、被忽视的隐形优势 <a class="header-anchor" href="#一、被忽视的隐形优势" aria-label="Permalink to &quot;一、被忽视的隐形优势&quot;">​</a></h2><p>在1989年致股东信中，巴菲特坦承：</p><blockquote><p>&quot;查理和我很少讨论税务策略——这通常意味着我们不愿意讨论的东西。但有一个税务方面的影响，我想你们应该了解，因为它会随着时间显著影响你们的投资结果。&quot;</p></blockquote><p>这个被忽视的主题就是：<strong>未实现资本利得递延纳税</strong>。</p><p>巴菲特解释了他的运作逻辑：</p><ul><li>伯克希尔持有的股票，如果卖出需要缴纳资本利得税</li><li>但只要不卖出，这笔税就&quot;暂存在政府那里&quot;</li><li>在这期间，这些&quot;暂存税款&quot;可以继续为伯克希尔工作，产生复利收益</li><li>&quot;政府是伯克希尔的沉默合伙人，而且是那种不收管理费的合伙人&quot;</li></ul><hr><h2 id="二、递延税复利的数学原理" tabindex="-1">二、递延税复利的数学原理 <a class="header-anchor" href="#二、递延税复利的数学原理" aria-label="Permalink to &quot;二、递延税复利的数学原理&quot;">​</a></h2><p>巴菲特在1989年信中用简单的数学说明了这个优势：</p><p>假设你投资100万，税率20%，每年增长10%：</p><p><strong>策略A：当年卖出，缴税后再投资</strong></p><ul><li>第1年：100万 × 1.10 = 110万，缴税：110万 × 20% = 22万，剩余：88万</li><li>第2年：88万 × 1.10 = 96.8万，缴税：19.36万，剩余：77.44万</li><li>……复利效果大打折扣</li></ul><p><strong>策略B：持有不卖，递延纳税</strong></p><ul><li>100万持续增长，税务负担&quot;暂存&quot;</li><li>政府相当于免息借给你这笔税款</li><li>20年后，递延税的优势可能高达数倍</li></ul><p>巴菲特的核心观点：当你选择持有一家优秀企业时，&quot;你的沉默合伙人（政府）的资金也在帮你工作&quot;。</p><hr><h2 id="三、与透视盈利的关系" tabindex="-1">三、与透视盈利的关系 <a class="header-anchor" href="#三、与透视盈利的关系" aria-label="Permalink to &quot;三、与透视盈利的关系&quot;">​</a></h2><p>递延税复利与**透视盈利（Look-Through Earnings）**概念紧密相关。</p><p>1980年，巴菲特首次提出留存收益的经济价值：</p><blockquote><p>&quot;如果一片森林长在我们部分拥有的树林里，哪怕财务报表没记录生长，我们依然拥有一部分树。&quot;</p></blockquote><p>1989年，他进一步深化：留存收益不仅创造了经济价值，还享受了<strong>税务递延</strong>的优势。</p><p>这意味着：</p><ul><li>持有优秀企业的时间越长，递延税的复利优势越大</li><li>频繁交易的投资者不仅承担了交易成本，还放弃了递延税的复利收益</li><li>巴菲特&quot;不想持十年就别持十分钟&quot;的原则，从税务角度也有量化依据</li></ul><hr><h2 id="四、对资本配置的影响" tabindex="-1">四、对资本配置的影响 <a class="header-anchor" href="#四、对资本配置的影响" aria-label="Permalink to &quot;四、对资本配置的影响&quot;">​</a></h2><p>递延税复利也影响了巴菲特的资本配置决策：</p><p><strong>为什么不愿意卖出</strong>：</p><ul><li>卖出需要缴纳资本利得税</li><li>新投资的回报不一定能弥补税务成本</li><li>&quot;实现一个漂亮的账面利润，然后去买一家普通企业，这是愚蠢的&quot;</li></ul><p><strong>伯克希尔的税务效率</strong>：</p><ul><li>伯克希尔大量持股的未实现资本利得高达数百亿美元</li><li>只要不卖出，这笔&quot;税款&quot;就继续在业务中产生复利</li><li>&quot;政府的沉默合伙人&quot;角色越来越重要</li></ul><hr><h2 id="五、实践意义" tabindex="-1">五、实践意义 <a class="header-anchor" href="#五、实践意义" aria-label="Permalink to &quot;五、实践意义&quot;">​</a></h2><p>对于普通投资者，巴菲特在1989年信中给出了建议：</p><blockquote><p>&quot;如果你选择了正确的企业，持有不动是积累财富的最有效方式——不仅是企业本身的复利，还有递延税带来的额外复利。&quot;</p></blockquote><p><strong>核心启示</strong>：</p><ol><li>频繁交易不仅浪费交易成本，还放弃了递延税的复利优势</li><li>在低税率或零税率账户（养老金等）中，可以更积极地交易</li><li>投资于能长期持有的优秀企业，&quot;税务效率&quot;本身就是一种竞争优势</li><li>伯克希尔的税务效率部分解释了为什么它能长期跑赢市场</li></ol><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./look-through-earnings.html">透视盈利 Look-Through Earnings</a> — 留存收益的经济价值</li><li><a href="./long-term.html">长期主义 Long-term</a> — 持有时间是复利最重要的变量</li><li><a href="./compounding.html">复利 Compounding</a> — 时间是伟大事业的朋友</li></ul><hr><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=核心总结">1989年：核心总结</a> → <a href="/01_letters/1989年/翻译.html">/01_letters/1989年/翻译</a></li><li><a href="/search.html?q=核心总结">2000年：核心总结</a> → <a href="/01_letters/2000年/翻译.html">/01_letters/2000年/翻译</a></li><li><a href="/search.html?q=核心总结">2019年：核心总结</a> → <a href="/01_letters/2019年/翻译.html">/01_letters/2019年/翻译</a></li></ul>',49)])])}const c=e(r,[["render",i]]);export{q as __pageData,c as default};
